        { id: 2, name: "Headphones", price: 150, category: "Electronics" },
        { id: 3, name: "Coffee Mug", price: 15, category: "Home" },
        { id: 4, name: "Desk Chair", price: 200, category: "Furniture" }
    ];

    // --- API Routes ---

    // 1. Get all products
    app.get('/api/products', (req, res) => {
        res.json(products);
    });

    // 2. Add a new product (Optional, for testing)
    app.post('/api/products', (req, res) => {
        const newProduct = { id: products.length + 1, ...req.body };
        products.push(newProduct);
        res.status(201).json(newProduct);
    });

    // --- Serving React Build in Production ---
    if (process.env.NODE_ENV === 'production') {
        // Serve static files from the React build folder
